-- Queen SDA — Sistema de Automatización de Datos V2.0 · Restaurante-bar La Reina
-- Importación inicial a Supabase desde el respaldo real del SDA.
-- Fuente: respaldo exportado el 2026-10-24 (SDA La Reina (panorama-mensual-la-reina)), archivo backup-sda-2026-10-24.json.
-- Generado por scripts/generate-import-sql.mjs usando el parser de la app
-- (src/lib/backupCore.mjs): las columnas salen del parser y el payload
-- jsonb de cada fila es el registro ORIGINAL completo del respaldo.
-- Cero datos inventados: ninguna cifra se ajusta ni se redondea aquí.
--
-- CÓMO APLICARLO: pégalo en el SQL Editor del proyecto Supabase «queen-sda»
-- y ejecútalo (el SQL Editor trabaja sin RLS; desde la app solo el admin
-- podría escribir). Es IDEMPOTENTE: se puede ejecutar las veces que sea
-- (insert ... on conflict do update por fecha en days y por id en receivables).
--
-- TOTALES DE CONTROL (verificados contra el respaldo antes de generar):
--   Días: 23 · Rango: 2026-10-01 → 2026-10-23
--   Ventas totales: 2662090 · Ganancia bruta: 667141 · Ganancia neta: 645576 · Cuadre total: 0
--   Cuentas: 115
--   Los 30 abonos que ya trae el respaldo quedan dentro de
--   receivables.payload (y de su saldo): la tabla payments es para los
--   abonos NUEVOS de Cobrar (origin='cobrar'), no se duplican aquí.

begin;

-- ===== Días (23) =====
on conflict (date) do update set
  ventas_dia = excluded.ventas_dia,
  ganancia_bruta = excluded.ganancia_bruta,
  ganancia_neta = excluded.ganancia_neta,
  cuadre = excluded.cuadre,
  payload = excluded.payload,
  imported_at = now();

-- ===== Cuentas por cobrar (115) =====
on conflict (id) do update set
  client = excluded.client,
  client_key = excluded.client_key,
  category = excluded.category,
  date = excluded.date,
  original_amount = excluded.original_amount,
  saldo = excluded.saldo,
  status = excluded.status,
  close_kind = excluded.close_kind,
  detail = excluded.detail,
  payload = excluded.payload,
  imported_at = now();

-- ===== Movimientos de la tarjeta (20) =====
-- El historial viaja TAL COMO el sistema original lo registró: la
-- marca «No es de La Reina» (excluded) de una fila que ya exista en el
-- servidor NO se pisa con la del respaldo (es decisión del dueño).
on conflict (id) do update set
  date = excluded.date,
  type = excluded.type,
  source = excluded.source,
  amount = excluded.amount,
  detail = excluded.detail,
  superseded = excluded.superseded,
  pase_id = excluded.pase_id,
  manual_id = excluded.manual_id,
  payment_credit_id = excluded.payment_credit_id,
  extra_id = excluded.extra_id,
  transfer_expense_id = excluded.transfer_expense_id,
  pase_kind = excluded.pase_kind,
  payload = excluded.payload,
  imported_at = now();

commit;

-- ===== Verificación tras importar (ejecutar y contrastar con el control) =====
-- Control: 23 días · 2026-10-01 → 2026-10-23 · ventas 2662090 · bruta 667141 · neta 645576 · cuadre 0 · 115 cuentas
select count(*) as dias, min(date) as desde, max(date) as hasta,
       sum(ventas_dia) as ventas, sum(ganancia_bruta) as bruta,
       sum(ganancia_neta) as neta, sum(cuadre) as cuadre
from public.days;
select count(*) as cuentas from public.receivables;
-- Control tarjeta: 20 movimientos · saldo derivado 32625 · pasado al banco 107625
select count(*) as movimientos,
       sum(case when not excluded and not superseded then amount else 0 end) as saldo
from public.transfer_movements;
select sum(abs(amount)) as pasado_al_banco from public.transfer_movements
where source = 'pase' and pase_kind = 'banco' and not excluded and not superseded;
